def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def pick_nearest(src, items):
        best = None
        best_d = None
        for item in items:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            p = (item[0], item[1])
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            target = max(corners, key=lambda c: manhattan(c, opp_pos))
            return step_toward(self_pos, target)
        return [-clamp_step(ox - sx), -clamp_step(oy - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = pick_nearest(self_pos, targets)
        if target is not None:
            return step_toward(self_pos, target)
        opp_terr = observation.get("opponent_territory") or []
        target = pick_nearest(self_pos, opp_terr)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    target = pick_nearest(self_pos, resources)
    if target is not None:
        return step_toward(self_pos, target)

    # denial / fallback: move toward opponent if no resources visible
    return step_toward(self_pos, opp_pos)

